create table public.epew_ffr_workforce_records(
 restaurant_unit_id text not null references public.epew_restaurant_units(restaurant_unit_id),kind text not null,record_key text not null,version integer not null check(version>0),data jsonb not null,updated_at timestamptz not null default now(),primary key(restaurant_unit_id,kind,record_key));
create table public.epew_ffr_workforce_revisions(id uuid primary key default gen_random_uuid(),restaurant_unit_id text not null,kind text not null,record_key text not null,version integer not null,previous_data jsonb,data jsonb not null,reason text not null,actor_user_id uuid,actor_email text not null,request_id uuid not null,request_input jsonb not null,created_at timestamptz not null default now(),unique(restaurant_unit_id,kind,record_key,version));
create index on public.epew_ffr_workforce_revisions(actor_user_id,request_id);
create table public.epew_ffr_payroll_exports(id uuid primary key default gen_random_uuid(),restaurant_unit_id text not null references public.epew_restaurant_units(restaurant_unit_id),period_start date not null,period_end date not null,provider text not null,lines jsonb not null,actor_user_id uuid not null,actor_email text not null,request_id uuid not null unique,reason text not null,created_at timestamptz not null default now());
create table public.epew_ffr_payroll_export_sources(restaurant_unit_id text not null,kind text not null,record_key text not null,export_id uuid not null references public.epew_ffr_payroll_exports(id),primary key(restaurant_unit_id,kind,record_key));
create function public.epew_ffr_workforce_append_only() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Workforce audit/export is append-only';end$$;
create trigger immutable_workforce_revisions before update or delete on public.epew_ffr_workforce_revisions for each row execute function public.epew_ffr_workforce_append_only();
create trigger immutable_payroll_exports before update or delete on public.epew_ffr_payroll_exports for each row execute function public.epew_ffr_workforce_append_only();
create trigger immutable_payroll_sources before update or delete on public.epew_ffr_payroll_export_sources for each row execute function public.epew_ffr_workforce_append_only();
alter table public.epew_ffr_workforce_records enable row level security;
alter table public.epew_ffr_workforce_revisions enable row level security;
alter table public.epew_ffr_payroll_exports enable row level security;
alter table public.epew_ffr_payroll_export_sources enable row level security;
revoke all on public.epew_ffr_workforce_records,public.epew_ffr_workforce_revisions,public.epew_ffr_payroll_exports,public.epew_ffr_payroll_export_sources from public,anon,authenticated;
grant select,insert,update on public.epew_ffr_workforce_records to service_role;
grant select,insert on public.epew_ffr_workforce_revisions,public.epew_ffr_payroll_exports,public.epew_ffr_payroll_export_sources to service_role;
revoke all on function public.epew_ffr_workforce_append_only() from public,anon,authenticated;
create function public.epew_ffr_workforce_save(p_actor uuid,p_email text,p_unit text,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare
 schema_rules jsonb := '{"applicant":[{"key":"full_name","label":"Full name","type":"text","required":true},{"key":"email","label":"Email","type":"email","required":false},{"key":"mobile","label":"Mobile","type":"text","required":false},{"key":"role_id","label":"Role ID","type":"text","required":false},{"key":"availability","label":"Availability","type":"textarea","required":false},{"key":"status","label":"Status","type":"select","required":true,"options":["received","reviewing","interview","offer","hired","not_selected","withdrawn"]},{"key":"notes","label":"Notes","type":"textarea","required":false}],"role":[{"key":"title","label":"Role title","type":"text","required":true},{"key":"duties","label":"Duties","type":"textarea","required":true},{"key":"requirements","label":"Training / certification requirements","type":"textarea","required":false},{"key":"status","label":"Status","type":"select","required":true,"options":["draft","active","inactive"]}],"employee":[{"key":"full_name","label":"Full name","type":"text","required":true},{"key":"applicant_id","label":"Applicant ID","type":"text","required":false},{"key":"email","label":"Email","type":"email","required":false},{"key":"mobile","label":"Mobile","type":"text","required":false},{"key":"role_id","label":"Role ID","type":"text","required":true},{"key":"start_date","label":"Start date","type":"date","required":false},{"key":"provider_employee_id","label":"Payroll provider employee ID","type":"text","required":false},{"key":"status","label":"Status","type":"select","required":true,"options":["onboarding","active","leave","inactive"]},{"key":"notes","label":"Notes","type":"textarea","required":false}],"availability":[{"key":"employee_id","label":"Employee ID","type":"text","required":true},{"key":"effective_date","label":"Effective date","type":"date","required":true},{"key":"availability","label":"Available days / time windows (New York time)","type":"textarea","required":true},{"key":"notes","label":"Notes","type":"textarea","required":false}],"training_plan":[{"key":"topic","label":"Training topic","type":"select","required":true,"options":["Food Fans culture","Food safety","Menu","Station","POS","Customer service","Pickup/delivery","Opening procedures","Closing procedures"]},{"key":"planned_date","label":"Planned training date","type":"date","required":true},{"key":"trainer","label":"Trainer","type":"text","required":true},{"key":"status","label":"Status","type":"select","required":true,"options":["planned","scheduled","cancelled"]},{"key":"notes","label":"Notes","type":"textarea","required":false}],"training":[{"key":"employee_id","label":"Employee ID","type":"text","required":true},{"key":"topic","label":"Training topic","type":"select","required":true,"options":["Food Fans culture","Food safety","Menu","Station","POS","Customer service","Pickup/delivery","Opening procedures","Closing procedures"]},{"key":"planned_date","label":"Planned training date","type":"date","required":true},{"key":"trainer","label":"Trainer","type":"text","required":true},{"key":"training_date","label":"Actual training date","type":"date","required":false},{"key":"status","label":"Status","type":"select","required":true,"options":["planned","in_progress","completed","needs_retraining","cancelled"]},{"key":"assessment","label":"Assessment result / evidence","type":"textarea","required":false},{"key":"certification","label":"Certification / evidence reference","type":"text","required":false},{"key":"retraining_date","label":"Retraining date","type":"date","required":false},{"key":"notes","label":"Notes","type":"textarea","required":false}],"certification":[{"key":"employee_id","label":"Employee ID","type":"text","required":true},{"key":"name","label":"Certification","type":"text","required":true},{"key":"issuer","label":"Issuer","type":"text","required":true},{"key":"reference","label":"Certificate reference","type":"text","required":true},{"key":"issued_date","label":"Issued date","type":"date","required":false},{"key":"expires_date","label":"Expiration date","type":"date","required":false},{"key":"status","label":"Status","type":"select","required":true,"options":["pending","verified","expired","revoked"]},{"key":"notes","label":"Notes","type":"textarea","required":false}],"schedule":[{"key":"employee_id","label":"Employee ID","type":"text","required":true},{"key":"starts_at","label":"Shift start (include UTC offset)","type":"text","required":true},{"key":"ends_at","label":"Shift end (include UTC offset)","type":"text","required":true},{"key":"station","label":"Station","type":"text","required":false},{"key":"status","label":"Status","type":"select","required":true,"options":["draft","published","cancelled"]},{"key":"notes","label":"Notes","type":"textarea","required":false}],"time_entry":[{"key":"employee_id","label":"Employee ID","type":"text","required":true},{"key":"clock_in","label":"Clock in (ISO date/time with UTC offset)","type":"text","required":true},{"key":"clock_out","label":"Clock out (ISO date/time with UTC offset)","type":"text","required":false},{"key":"unpaid_break_minutes","label":"Unpaid break minutes","type":"number","required":true},{"key":"status","label":"Status","type":"select","required":true,"options":["open","pending","approved","rejected"]},{"key":"approval_evidence","label":"Time review evidence","type":"textarea","required":false},{"key":"notes","label":"Notes","type":"textarea","required":false}],"attendance":[{"key":"employee_id","label":"Employee ID","type":"text","required":true},{"key":"work_date","label":"Work date","type":"date","required":true},{"key":"schedule_id","label":"Schedule ID","type":"text","required":false},{"key":"status","label":"Status","type":"select","required":true,"options":["present","late","absent","excused"]},{"key":"notes","label":"Notes","type":"textarea","required":false}],"performance":[{"key":"employee_id","label":"Employee ID","type":"text","required":true},{"key":"review_date","label":"Review date","type":"date","required":true},{"key":"reviewer","label":"Reviewer","type":"text","required":true},{"key":"assessment","label":"Assessment","type":"textarea","required":true},{"key":"next_action","label":"Next action","type":"textarea","required":false},{"key":"notes","label":"Notes","type":"textarea","required":false}],"document":[{"key":"employee_id","label":"Employee ID","type":"text","required":true},{"key":"title","label":"Document title","type":"text","required":true},{"key":"attachment_id","label":"Private launch-workspace attachment UUID","type":"text","required":true},{"key":"category","label":"Category","type":"text","required":true},{"key":"expires_date","label":"Expiration date","type":"date","required":false},{"key":"notes","label":"Notes","type":"textarea","required":false}],"manager_note":[{"key":"employee_id","label":"Employee ID","type":"text","required":true},{"key":"note_date","label":"Note date","type":"date","required":true},{"key":"note","label":"Manager note","type":"textarea","required":true},{"key":"follow_up_date","label":"Follow-up date","type":"date","required":false}],"payroll":[{"key":"employee_id","label":"Employee ID","type":"text","required":true},{"key":"period_start","label":"Pay period start","type":"date","required":true},{"key":"period_end","label":"Pay period end","type":"date","required":true},{"key":"regular_hours","label":"Manager-reviewed regular hours","type":"number","required":true},{"key":"overtime_hours","label":"Manager-reviewed overtime hours","type":"number","required":true},{"key":"rate_cents","label":"Approved hourly rate (USD cents)","type":"number","required":true},{"key":"time_entry_ids","label":"Approved time entry IDs (comma separated)","type":"textarea","required":true},{"key":"status","label":"Status","type":"select","required":true,"options":["draft","approved"]},{"key":"approval_evidence","label":"Payroll review / classification evidence","type":"textarea","required":false},{"key":"notes","label":"Notes","type":"textarea","required":false}]}'::jsonb;
 k text:=p_input->>'kind';rk text:=p_input->>'record_key';d jsonb:=p_input->'data';expected integer:=(p_input->>'expected_version')::integer;req uuid:=(p_input->>'request_id')::uuid;
 old public.epew_ffr_workforce_records;rev public.epew_ffr_workforce_revisions;ex public.epew_ffr_payroll_exports;field jsonb;v jsonb;ref text;emp jsonb;t jsonb;minutes numeric;total numeric;regular numeric;ot numeric;lines jsonb;source_ids text[];entry public.epew_ffr_workforce_records;new_key text;planned jsonb;
 begin
 if p_actor is null or p_email is null or not exists(select 1 from public.user_roles where role='administrator' and (user_id=p_actor or(user_id is null and lower(email)=lower(p_email)))) then raise exception using errcode='42501',message='Administrator required';end if;
 if req is null or coalesce(length(btrim(p_input->>'reason')),0) not between 1 and 4000 or not exists(select 1 from public.epew_restaurant_units where restaurant_unit_id=p_unit) then raise exception using errcode='22023',message='Invalid request';end if;
 -- Serialize unit mutations so time approval, payroll exports and corrections cannot race.
 perform pg_advisory_xact_lock(hashtextextended('workforce:'||p_unit,0));
 select * into rev from public.epew_ffr_workforce_revisions where actor_user_id=p_actor and request_id=req order by created_at limit 1;
 if found then if rev.restaurant_unit_id<>p_unit or rev.request_input<>p_input then raise exception using errcode='22023',message='Request ID reused';end if;return jsonb_build_object('saved',true,'replayed',true,'version',rev.version);end if;
 select * into ex from public.epew_ffr_payroll_exports where request_id=req;
 if found then if ex.restaurant_unit_id<>p_unit or ex.actor_user_id<>p_actor or ex.period_start::text<>p_input->>'period_start' or ex.period_end::text<>p_input->>'period_end' or ex.provider<>p_input->>'provider' or ex.reason<>p_input->>'reason' then raise exception using errcode='22023',message='Request ID reused';end if;return jsonb_build_object('saved',true,'export_id',ex.id,'replayed',true);end if;
 if p_input->>'action'='export' then
 if (p_input->>'period_start')::date>(p_input->>'period_end')::date or coalesce(length(btrim(p_input->>'provider')),0) not between 1 and 200 then raise exception using errcode='22023',message='Invalid export period/provider';end if;
 select jsonb_agg(r.data||jsonb_build_object('payroll_record_id',r.record_key,'provider_employee_id',e.data->>'provider_employee_id') order by r.record_key) into lines from public.epew_ffr_workforce_records r join public.epew_ffr_workforce_records e on e.restaurant_unit_id=r.restaurant_unit_id and e.kind='employee' and e.record_key=r.data->>'employee_id'
 where r.restaurant_unit_id=p_unit and r.kind='payroll' and r.data->>'status'='approved' and r.data->>'period_start'=p_input->>'period_start' and r.data->>'period_end'=p_input->>'period_end' and not exists(select 1 from public.epew_ffr_payroll_export_sources s where s.restaurant_unit_id=p_unit and s.kind='payroll' and s.record_key=r.record_key);
 if lines is null then raise exception using errcode='22023',message='No unexported approved payroll lines';end if;
 if exists(select 1 from jsonb_array_elements(lines) x where nullif(btrim(x->>'provider_employee_id'),'') is null) then raise exception using errcode='22023',message='Provider employee ID required';end if;
 -- Recheck every approved line against current approved source time before export.
 for t in select value from jsonb_array_elements(lines) loop
 source_ids:=regexp_split_to_array(t->>'time_entry_ids','\s*,\s*');total:=0;
 foreach ref in array source_ids loop
 select * into entry from public.epew_ffr_workforce_records where restaurant_unit_id=p_unit and kind='time_entry' and record_key=ref;
 if not found or entry.data->>'status'<>'approved' or entry.data->>'employee_id'<>t->>'employee_id' or ((entry.data->>'clock_in')::timestamptz at time zone 'America/New_York')::date<(t->>'period_start')::date or ((entry.data->>'clock_out')::timestamptz at time zone 'America/New_York')::date>(t->>'period_end')::date or exists(select 1 from public.epew_ffr_payroll_export_sources where restaurant_unit_id=p_unit and kind='time_entry' and record_key=ref) then raise exception using errcode='22023',message='Source time changed or exported';end if;
 total:=total+extract(epoch from((entry.data->>'clock_out')::timestamptz-(entry.data->>'clock_in')::timestamptz))/3600-(entry.data->>'unpaid_break_minutes')::numeric/60;
 end loop;
 if abs(total-(t->>'regular_hours')::numeric-(t->>'overtime_hours')::numeric)>0.0001 then raise exception using errcode='22023',message='Time total changed; review payroll again';end if;
 end loop;
 insert into public.epew_ffr_payroll_exports(restaurant_unit_id,period_start,period_end,provider,lines,actor_user_id,actor_email,request_id,reason) values(p_unit,(p_input->>'period_start')::date,(p_input->>'period_end')::date,p_input->>'provider',lines,p_actor,p_email,req,p_input->>'reason') returning * into ex;
 for t in select value from jsonb_array_elements(lines) loop
 insert into public.epew_ffr_payroll_export_sources values(p_unit,'payroll',t->>'payroll_record_id',ex.id);
 foreach ref in array regexp_split_to_array(t->>'time_entry_ids','\s*,\s*') loop insert into public.epew_ffr_payroll_export_sources values(p_unit,'time_entry',ref,ex.id);end loop;
 end loop;
 return jsonb_build_object('saved',true,'export_id',ex.id);
 end if;
 if schema_rules->k is null or rk is null or rk!~'^[A-Za-z0-9_.:-]{1,100}$' or expected is null or expected<0 or d is null or jsonb_typeof(d)<>'object' then raise exception using errcode='22023',message='Invalid record';end if;
 if exists(select 1 from jsonb_object_keys(d) key where not exists(select 1 from jsonb_array_elements(schema_rules->k) f where f->>'key'=key)) then raise exception using errcode='22023',message='Unknown field';end if;
 for field in select value from jsonb_array_elements(schema_rules->k) loop
 v:=d->(field->>'key');
 if coalesce((field->>'required')::boolean,false) and (v is null or v='null'::jsonb or v='""'::jsonb) then raise exception using errcode='22023',message='Required field';end if;
 if v is null or v='null'::jsonb or v='""'::jsonb then continue;end if;
 if field->>'type'='number' then if jsonb_typeof(v)<>'number' or (d->>(field->>'key'))::numeric<0 then raise exception using errcode='22023',message='Invalid number';end if;
 else if jsonb_typeof(v)<>'string' or length(d->>(field->>'key'))>12000 then raise exception using errcode='22023',message='Invalid text';end if;
 if field->'options' is not null and not exists(select 1 from jsonb_array_elements_text(field->'options') opt where opt=d->>(field->>'key')) then raise exception using errcode='22023',message='Invalid option';end if;
 if field->>'type'='date' then perform (d->>(field->>'key'))::date;end if;end if;
 end loop;
 select * into old from public.epew_ffr_workforce_records where restaurant_unit_id=p_unit and kind=k and record_key=rk for update;
 if coalesce(old.version,0)<>expected then raise exception using errcode='40001',message='Record changed';end if;
 if exists(select 1 from public.epew_ffr_payroll_export_sources where restaurant_unit_id=p_unit and kind=k and record_key=rk) then raise exception using errcode='22023',message='Exported records locked; use a provider-approved adjustment';end if;
 if d?'employee_id' then select data into emp from public.epew_ffr_workforce_records where restaurant_unit_id=p_unit and kind='employee' and record_key=d->>'employee_id';if emp is null then raise exception using errcode='22023',message='Employee not found in restaurant';end if;end if;
 if nullif(d->>'role_id','') is not null and not exists(select 1 from public.epew_ffr_workforce_records where restaurant_unit_id=p_unit and kind='role' and record_key=d->>'role_id') then raise exception using errcode='22023',message='Role not found';end if;
 if nullif(d->>'applicant_id','') is not null and not exists(select 1 from public.epew_ffr_workforce_records where restaurant_unit_id=p_unit and kind='applicant' and record_key=d->>'applicant_id') then raise exception using errcode='22023',message='Applicant not found';end if;
 if k='training' and d->>'status'='completed' and (nullif(d->>'training_date','') is null or (d->>'training_date')::date>(now() at time zone 'America/New_York')::date or nullif(btrim(d->>'assessment'),'') is null) then raise exception using errcode='22023',message='Actual training date and assessment evidence required';end if;
 if k='certification' and nullif(d->>'expires_date','') is not null and nullif(d->>'issued_date','') is not null and (d->>'expires_date')::date<(d->>'issued_date')::date then raise exception using errcode='22023',message='Invalid certification dates';end if;
 if k='document' and not exists(select 1 from public.epew_restaurant_work_files where restaurant_unit_id=p_unit and id=(d->>'attachment_id')::uuid) then raise exception using errcode='22023',message='Private document attachment required';end if;
 if k='schedule' then if d->>'starts_at'!~'(Z|[+-][0-9]{2}:[0-9]{2})$' or d->>'ends_at'!~'(Z|[+-][0-9]{2}:[0-9]{2})$' or (d->>'ends_at')::timestamptz<=(d->>'starts_at')::timestamptz then raise exception using errcode='22023',message='Invalid shift timestamps';end if;end if;
 if k='attendance' and nullif(d->>'schedule_id','') is not null and not exists(select 1 from public.epew_ffr_workforce_records where restaurant_unit_id=p_unit and kind='schedule' and record_key=d->>'schedule_id' and data->>'employee_id'=d->>'employee_id') then raise exception using errcode='22023',message='Schedule/employee mismatch';end if;
 if k='time_entry' then
 if d->>'clock_in'!~'(Z|[+-][0-9]{2}:[0-9]{2})$' or (d->>'clock_in')::timestamptz>now() or (d->>'unpaid_break_minutes')::numeric<>trunc((d->>'unpaid_break_minutes')::numeric) then raise exception using errcode='22023',message='Invalid clock in/break';end if;
 if nullif(d->>'clock_out','') is null then if d->>'status'<>'open' then raise exception using errcode='22023',message='Clock out required';end if;
 else if d->>'clock_out'!~'(Z|[+-][0-9]{2}:[0-9]{2})$' or (d->>'clock_out')::timestamptz>now() or (d->>'clock_out')::timestamptz<=(d->>'clock_in')::timestamptz or d->>'status'='open' then raise exception using errcode='22023',message='Invalid clock out';end if;
 minutes:=extract(epoch from((d->>'clock_out')::timestamptz-(d->>'clock_in')::timestamptz))/60;
 if (d->>'unpaid_break_minutes')::numeric>minutes then raise exception using errcode='22023',message='Break exceeds shift';end if;end if;
 if d->>'status'<>'rejected' and exists(select 1 from public.epew_ffr_workforce_records r where r.restaurant_unit_id=p_unit and r.kind='time_entry' and r.record_key<>rk and r.data->>'employee_id'=d->>'employee_id' and r.data->>'status'<>'rejected' and (r.data->>'clock_in')::timestamptz<coalesce(nullif(d->>'clock_out','')::timestamptz,'infinity'::timestamptz) and (d->>'clock_in')::timestamptz<coalesce(nullif(r.data->>'clock_out','')::timestamptz,'infinity'::timestamptz)) then raise exception using errcode='22023',message='Overlapping time entry';end if;
 if d->>'status'='approved' and nullif(btrim(d->>'approval_evidence'),'') is null then raise exception using errcode='22023',message='Time approval evidence required';end if;
 end if;
 if k='payroll' then
 if (d->>'period_start')::date>(d->>'period_end')::date or (d->>'rate_cents')::numeric<>trunc((d->>'rate_cents')::numeric) then raise exception using errcode='22023',message='Invalid payroll dates/rate';end if;
 if d->>'status'='approved' then
 if nullif(btrim(d->>'approval_evidence'),'') is null or (d->>'rate_cents')::numeric<=0 then raise exception using errcode='22023',message='Payroll approval evidence/rate required';end if;
 source_ids:=regexp_split_to_array(d->>'time_entry_ids','\s*,\s*');total:=0;
 if array_length(source_ids,1)<>(select count(distinct x) from unnest(source_ids) x) then raise exception using errcode='22023',message='Duplicate time reference';end if;
 foreach ref in array source_ids loop
 select * into entry from public.epew_ffr_workforce_records where restaurant_unit_id=p_unit and kind='time_entry' and record_key=ref;
 if not found or entry.data->>'status'<>'approved' or entry.data->>'employee_id'<>d->>'employee_id' or ((entry.data->>'clock_in')::timestamptz at time zone 'America/New_York')::date<(d->>'period_start')::date or ((entry.data->>'clock_out')::timestamptz at time zone 'America/New_York')::date>(d->>'period_end')::date then raise exception using errcode='22023',message='Approved time in pay period required';end if;
 total:=total+extract(epoch from((entry.data->>'clock_out')::timestamptz-(entry.data->>'clock_in')::timestamptz))/3600-(entry.data->>'unpaid_break_minutes')::numeric/60;
 end loop;
 regular:=(d->>'regular_hours')::numeric;ot:=(d->>'overtime_hours')::numeric;
 if abs(total-regular-ot)>0.0001 then raise exception using errcode='22023',message='Payroll hours must equal approved time';end if;
 if exists(select 1 from public.epew_ffr_workforce_records r where r.restaurant_unit_id=p_unit and r.kind='payroll' and r.record_key<>rk and r.data->>'status'='approved' and regexp_split_to_array(r.data->>'time_entry_ids','\s*,\s*') && source_ids) then raise exception using errcode='22023',message='Time already assigned to payroll';end if;
 end if;end if;
 insert into public.epew_ffr_workforce_records values(p_unit,k,rk,expected+1,d,clock_timestamp()) on conflict(restaurant_unit_id,kind,record_key) do update set version=excluded.version,data=excluded.data,updated_at=excluded.updated_at;
 insert into public.epew_ffr_workforce_revisions(restaurant_unit_id,kind,record_key,version,previous_data,data,reason,actor_user_id,actor_email,request_id,request_input) values(p_unit,k,rk,expected+1,old.data,d,p_input->>'reason',p_actor,p_email,req,p_input);
 if k='employee' and expected=0 then
 for planned in select data from public.epew_ffr_workforce_records where restaurant_unit_id=p_unit and kind='training_plan' and data->>'status'<>'cancelled' loop
 new_key:=rk||':'||replace(lower(planned->>'topic'),' ','_');
 t:=jsonb_build_object('employee_id',rk,'topic',planned->>'topic','planned_date',planned->>'planned_date','trainer',planned->>'trainer','status','planned','training_date',null,'assessment',null,'certification',null,'retraining_date',null,'notes','Created from staff training plan; completion requires evidence.');
 insert into public.epew_ffr_workforce_records values(p_unit,'training',new_key,1,t,now());
 insert into public.epew_ffr_workforce_revisions(restaurant_unit_id,kind,record_key,version,data,reason,actor_user_id,actor_email,request_id,request_input) values(p_unit,'training',new_key,1,t,p_input->>'reason',p_actor,p_email,req,p_input);
 end loop;end if;
 return jsonb_build_object('saved',true,'version',expected+1);
 end$$;
revoke all on function public.epew_ffr_workforce_save(uuid,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.epew_ffr_workforce_save(uuid,text,text,jsonb) to service_role;
-- Seed only the authorized plan, never fictitious employees or completion evidence.
insert into public.epew_ffr_workforce_records(restaurant_unit_id,kind,record_key,version,data)
select 'FFR-001','training_plan','PLAN-'||n,1,jsonb_build_object('topic',topic,'planned_date','2026-11-09','trainer',case when topic='POS' then 'Guy' else 'Samuel Nelson' end,'status','planned','notes','Samuel directive, October 30, 2026. Time/location and employee attendance pending.') from unnest(array['Food Fans culture','Food safety','Menu','Station','POS','Customer service','Pickup/delivery','Opening procedures','Closing procedures']) with ordinality t(topic,n);
insert into public.epew_ffr_workforce_revisions(restaurant_unit_id,kind,record_key,version,data,reason,actor_email,request_id,request_input) select restaurant_unit_id,kind,record_key,version,data,'Samuel authorized Food Fans workforce V1 and staff training plan.','system:technical-assistant',gen_random_uuid(),jsonb_build_object('source','Samuel directive October 30, 2026') from public.epew_ffr_workforce_records where kind='training_plan';
